    <script>
        function openTab(evt, tabName) {
            let i, tabcontent, tablinks;
            tabcontent = document.getElementsByClassName("tab-content");
            for (i = 0; i < tabcontent.length; i++) {
                tabcontent[i].style.display = "none";
                tabcontent[i].classList.remove("active");
            }
            tablinks = document.getElementsByClassName("tab-button");
            for (i = 0; i < tablinks.length; i++) {
                tablinks[i].classList.remove("active");
            }
            const currentTabContent = document.getElementById(tabName);
            if (currentTabContent) {
                currentTabContent.style.display = "block";
                currentTabContent.classList.add("active");
                const bodyBg = currentTabContent.getAttribute('data-body-bg');
                document.body.style.background = bodyBg || '#181a28'; 
            }
            if (evt && evt.currentTarget) {
                 evt.currentTarget.classList.add("active");
            }
        }

        document.addEventListener('DOMContentLoaded', function() {
            const contentWrappersToClean = [
                document.querySelector('#contentTab1 .whimsy-tp-content-v2'),
                document.querySelector('#contentTab2 .novel-decide-content-optimized'),
                document.querySelector('#contentTab3 .contentTab3-text-wrapper'),
