                document.querySelector('#contentTab9 .plain-text-content-wrapper'),
                document.querySelector('#contentTab10 .flower-garden-content-wrapper')
            ];

            const decoder = document.createElement('textarea');
            contentWrappersToClean.forEach(wrapper => {
                if (wrapper) {
                    let htmlContent = wrapper.innerHTML;
                    decoder.innerHTML = htmlContent;
                    let decodedHtml = decoder.value;
                    let cleanedHtml = decodedHtml.replace(/<br\s*\/?>/gi, '');
                    cleanedHtml = cleanedHtml.replace(/<\/br>/gi, ''); 
                    if (wrapper.innerHTML !== cleanedHtml) {
                        wrapper.innerHTML = cleanedHtml;
                    }
                }
            });

            const activeTabOnLoad = document.querySelector('.tab-content.active');
            if (activeTabOnLoad) {
                const initialBg = activeTabOnLoad.getAttribute('data-body-bg');
                document.body.style.background = initialBg || '#f0f5f0';
            } else {
                 const firstButton = document.querySelector('.tab-buttons .tab-button:first-child');
                if (firstButton) {
                    firstButton.click(); 
                } else {
                    document.body.style.background = '#f0f5f0'; 
                }
            }
        });
